void fillngcpp(
        const int nc, 
        const int gg, 
        const IntegerVector &grp, 
        std::vector<int> &ng) {
    int g, n;
    // Count number per group (not used for CL)                
    // Assume histories sorted by group = individual           
    // CH are numbered 0 <= n < nc in C code                  
    for (g=0; g<gg; g++)
        ng[g] = 0;
    for (n=0; n<nc; n++) { 
        g = grp[n] - 1; 
        ng[g]++;
    }
}

